# ---------------------------------------------------------------- Taguchi
L("metode-taguchi",
  [(r"Faktor kendali dan faktor gangguan",
    [r"Gagasan inti Taguchi adalah rancangan kokoh (robust design): memilih taraf faktor kendali sehingga respon tetap baik walaupun faktor gangguan (yang sulit atau mahal dikendalikan dalam produksi) berubah. Faktor kendali ditempatkan pada larik dalam (inner array) dan faktor gangguan pada larik luar (outer array); setiap baris larik dalam dijalankan pada semua kondisi larik luar.",
     r"Rasio SN merangkum rata-rata dan keragaman respon di atas kondisi gangguan dalam satu angka; taraf yang memaksimumkan SN adalah taraf yang kokoh."],
    [r"SN_{\text{besar}}=-10\log_{10}\Big(\frac{1}{n}\sum\frac{1}{y_i^2}\Big),\quad SN_{\text{kecil}}=-10\log_{10}\Big(\frac{1}{n}\sum y_i^2\Big),\quad SN_{\text{nominal}}=10\log_{10}\frac{\bar{y}^2}{s^2}"]),
   (r"Larik ortogonal dan grafik linear",
    [r"Larik ortogonal adalah faktorial pecahan beresolusi rendah dalam notasi Taguchi: \(L_4(2^3)\), \(L_8(2^7)\), \(L_9(3^4)\), \(L_{18}(2^1\times3^7)\). Setiap pasangan kolom seimbang. Bila interaksi tertentu perlu ditaksir, grafik linear atau tabel interaksi menunjukkan kolom mana yang harus dikosongkan untuk menampung interaksi itu."],
    []),
   (r"Kritik dan pendekatan model respon",
    [r"Statistikawan (Box, Nair, dan lainnya) mengkritik beberapa aspek: rasio SN mencampur rata-rata dan ragam sehingga efeknya sulit dipisahkan, larik resolusi III dapat menyesatkan bila ada interaksi, dan analisis 'pilih taraf terbaik' tanpa uji formal rawan efek palsu.",
     r"Pendekatan alternatif memodelkan rata-rata dan logaritma simpangan baku secara terpisah, atau memasukkan faktor gangguan langsung ke model respon (response model approach) sehingga interaksi kendali × gangguan, sumber kekokohan yang sebenarnya, dapat ditaksir eksplisit."],
    [r"\ln s=\gamma_0+\sum\gamma_jx_j,\qquad y=\beta_0+\sum\beta_jx_j+\sum\delta_kz_k+\sum\sum\phi_{jk}x_jz_k+\varepsilon"]),
   (r"Prediksi dan konfirmasi",
    [r"Setelah taraf optimum dipilih, SN pada kombinasi itu diprediksi dengan model aditif dari efek faktor yang berpengaruh. Percobaan konfirmasi di kombinasi optimum wajib dilakukan; bila hasilnya jauh dari prediksi, kemungkinan ada interaksi yang diabaikan."],
    [r"\widehat{SN}_{\text{opt}}=\overline{SN}+\sum_{j\in\text{faktor nyata}}\big(\overline{SN}_{j,\text{opt}}-\overline{SN}\big)"])],
  [(r"Respon yang ingin kecil (kekasaran permukaan) teramati 2, 3, dan 2 pada tiga kondisi gangguan. Hitung SN kecil-lebih-baik.",
    r"\(\frac13(4+9+4)=5{,}667\); \(SN=-10\log_{10}5{,}667=-7{,}53\) dB."),
   (r"Berapa faktor dua taraf maksimum yang dapat ditempatkan pada \(L_8\)?",
    r"Tujuh faktor (\(L_8(2^7)\)), bila tidak ada interaksi yang ditaksir."),
   (r"Apa kritik utama terhadap rasio SN nominal-terbaik?",
    r"Rasio itu mencampur rata-rata dan ragam dalam satu angka, sehingga faktor yang mengubah rata-rata dan faktor yang mengubah ragam sulit dibedakan; lebih jelas bila rata-rata dan log simpangan baku dimodelkan terpisah."),
   (r"Rata-rata SN keseluruhan 27,8 dB. Faktor A pada taraf terbaik 28,5 dB, faktor C pada taraf terbaik 28,5 dB, faktor B tidak berpengaruh. Prediksi SN optimum.",
    r"\(27{,}8+(28{,}5-27{,}8)+(28{,}5-27{,}8)=29{,}2\) dB."),
   (r"Hasil percobaan konfirmasi jauh di bawah SN prediksi. Apa kemungkinan penyebabnya?",
    r"Interaksi antar faktor kendali yang alias dengan efek utama pada larik ortogonal, atau faktor gangguan baru yang tidak tercakup larik luar. Model aditif menjadi tidak berlaku.")],
  [R_PHADKE, R_WU, R_MONT],
  contoh2=dict(judul="Contoh hitung kedua: L4 dengan dua kondisi gangguan",
               soal="Tiga faktor kendali dua taraf (A, B, C) ditempatkan pada L4(2³). Setiap baris dijalankan pada dua kondisi gangguan; respon ingin besar (kekuatan tarik). Data di tabel.",
               data=[["Run", "A", "B", "C", "y (N1, N2)", "SN (dB)"], ["1", "1", "1", "1", "20, 22", "26,41"], ["2", "1", "2", "2", "25, 24", "27,78"], ["3", "2", "1", "2", "28, 30", "29,23"], ["4", "2", "2", "1", "26, 23", "27,73"]],
               langkah=[("SN besar-lebih-baik untuk run 1.", r"SN_1=-10\log_{10}\Big[\tfrac12\Big(\tfrac{1}{20^2}+\tfrac{1}{22^2}\Big)\Big]=26{,}41"),
                        ("Rata-rata SN tiap taraf faktor.", r"A_1=27{,}10,\ A_2=28{,}48;\qquad B_1=27{,}82,\ B_2=27{,}76;\qquad C_1=27{,}07,\ C_2=28{,}51"),
                        ("Pilih taraf dengan SN tertinggi dan prediksi SN optimum (B diabaikan).", r"\overline{SN}=27{,}79,\qquad \widehat{SN}_{A_2C_2}=27{,}79+0{,}69+0{,}72=29{,}20")],
               simpul="Kombinasi kokoh adalah A2 dan C2; B hampir tidak berpengaruh sehingga tarafnya dapat dipilih yang paling murah. Kombinasi A2B1C2 kebetulan sama dengan run 3 (SN 29,23), cocok dengan prediksi 29,20; tetap jalankan konfirmasi dengan ulangan baru."))
